import{c as e,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Claude Haiku 4.5 System Card","description":"","frontmatter":{"url":"https://www.anthropic.com/claude-haiku-4-5-system-card","title":"Claude Haiku 4.5 System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["Anthropic"],"domains":["system-card"],"published_date":"2025-10-01T00:00:00.000Z","source_url":"https://www.anthropic.com/claude-haiku-4-5-system-card","web_only":true},"headers":[],"relativePath":"research/papers/2025-10-01-claude-haiku-4-5-system-card.md","filePath":"research/papers/2025-10-01-claude-haiku-4-5-system-card.md","lastUpdated":1785909234000}'),s={name:"research/papers/2025-10-01-claude-haiku-4-5-system-card.md"};function i(c,a,d,l,n,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="claude-haiku-4-5-system-card" tabindex="-1">Claude Haiku 4.5 System Card <a class="header-anchor" href="#claude-haiku-4-5-system-card" aria-label="Permalink to &quot;Claude Haiku 4.5 System Card&quot;">​</a></h1><p><strong>Source</strong>: Anthropic 官方 system card（web-only，無 arXiv PDF）— <a href="https://www.anthropic.com/claude-haiku-4-5-system-card" target="_blank" rel="noreferrer">https://www.anthropic.com/claude-haiku-4-5-system-card</a> （原始 URL 307 重導向至官方 PDF <code>www-cdn.anthropic.com/.../Claude%20Haiku%204.5%20System%20Card.pdf</code>，內容相同。） <strong>Published</strong>: October 2025（清單記 2025-10-01；模型公開發布日為 2025-10-15）</p><blockquote><p>依官方公開資訊整理；數字以可交叉驗證者為主，不確定處保守描述。</p></blockquote><hr><h2 id="摘要-依官網內容整理" tabindex="-1">摘要（依官網內容整理） <a class="header-anchor" href="#摘要-依官網內容整理" aria-label="Permalink to &quot;摘要（依官網內容整理）&quot;">​</a></h2><p>Haiku 4.5 為成本/速度導向的小型旗艦，但 coding 能力已逼近前代中大型模型，定位為 multi-agent fan-out 與高吞吐場景的經濟選擇。安全檔位較低（ASL-2）。</p><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li><strong>Claude Haiku 4.5</strong>：最快、最便宜的 4.5 世代檔位；主打高並行、低延遲、multi-agent。</li></ul><h3 id="關鍵能力-安全評估數字-依官方公開資訊整理" tabindex="-1">關鍵能力 / 安全評估數字（依官方公開資訊整理） <a class="header-anchor" href="#關鍵能力-安全評估數字-依官方公開資訊整理" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字（依官方公開資訊整理）&quot;">​</a></h3><ul><li><strong>SWE-bench Verified</strong>：<strong>73.3%</strong>（500 題完整集，50 trials 平均，無 test-time compute，128K thinking budget，bash + 字串替換編輯雙工具 scaffold）。</li><li><strong>AI Safety Level</strong>：<strong>ASL-2 Standard</strong>（低於同期 Sonnet 4.5 / Opus 4.1 的 ASL-3）。</li><li><strong>Pricing</strong>：約 <strong>$1 / 1M input、$5 / 1M output</strong>；prompt caching 最高省 90%、batch 省 50%。</li></ul><h3 id="值得注意章節" tabindex="-1">值得注意章節 <a class="header-anchor" href="#值得注意章節" aria-label="Permalink to &quot;值得注意章節&quot;">​</a></h3><ul><li>後續官方溯及性陳述指出：自 Haiku 4.5 起的每個 Claude 模型在勒索評測上皆 <strong>0%</strong>——即 Haiku 4.5 是「代理失準勒索行為清零」的世代起點。</li></ul><hr><h2 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h2><ul><li><strong><code>pilot</code>（tier=cost，原 <code>haiku-pilot</code>） 核心參照</strong>：本卡是 <code>pilot</code>（tier=cost，原 <code>haiku-pilot</code>）（cost-first）的能力底座；73.3% SWE-bench 證明「便宜檔位仍可做實質 coding」，支持「先調 effort 再換 model」的 effort-first 原則。</li><li><strong>multi-agent fan-out 經濟性 ↔ <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）</strong>：Haiku 低成本使「fan-out 上限 4 / dynamic workflow ≤16」的並行委派在預算上可行——平行 sub-agent 用 Haiku 跑研究/靜態分析很划算。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>ASL-2 ↔ 能力下限</strong>：<code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）「能力下限」提醒——低檔位適合 on-rails 任務（重構/摘要），off-rails 仍須升級。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li></ul>',17)])])}const p=e(s,[["render",i]]);export{m as __pageData,p as default};
